test('createInvoice applies gold tier discount (5%)', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount (2.5%)', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount (0%)', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice explicit discount (0) overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 0 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice explicit discount overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 10 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice with multiple lines applies tier discount to all', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
  assert.equal(result.value.lines[1].discountPercent, 5);
});

test('createInvoice with mixed explicit and tier discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
  assert.equal(result.value.lines[1].discountPercent, 5);
});

test('addLine applies tier discount to new line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'STICKER', qty: 100 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 5);
});

test('addLine with explicit discount overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'STICKER', qty: 100, discountPercent: 15 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 15);
});

test('invoiceTotals with tier discount applied', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 × €95.00 = €950.00
  // 5% tier discount = €47.50
  // Total = €950.00 - €47.50 = €902.50
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.total, 90250);
});

test('invoiceTotals with silver tier (2.5%) discount', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 1 × €1,200.00 = €1,200.00
  // 2.5% tier discount = €30.00
  // Total = €1,200.00 - €30.00 = €1,170.00
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 3000);
  assert.equal(totals.total, 117000);
});

test('invoiceTotals with standard tier (0%) discount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'STICKER', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 100 × €0.50 = €50.00
  // 0% tier discount = €0.00
  // Total = €50.00 - €0.00 = €50.00
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 5000);
});

